/**
 * Recipe guards — regression tests for four failure modes that reached a feature branch
 * despite passing `tsc`, `eslint`, `vitest`, CodeRabbit and the Storybook a11y run.
 *
 * All four share a shape: the value is a *valid* `SystemStyleObject` entry, so TypeScript is
 * satisfied; no lint rule covers it; and nothing asserts layout. Each one renders plausible,
 * wrong output that is only visible by opening the page.
 *
 *   1. A spacing-scale key on a sizing property. Chakra resolves `width`/`height`/`boxSize`
 *      through `theme.sizes`, not `theme.space`. The Zimmermann named scale is registered as
 *      `space` only (deliberately — see foundation/sizes.ts), so `width: 'xl'` silently reads
 *      Chakra's default `sizes.xl` = 36rem. It shipped a 576px icon and collapsed the footer.
 *
 *   2. The same trap on a typography property. `fontSizes`/`lineHeights`/`letterSpacings` are
 *      deliberately NOT registered either (theme/index.ts explains why), so a bare key reads
 *      Chakra's default or resolves to nothing at all. See TYPOGRAPHY_PROPS below.
 *
 *   3. A recipe key that collides with a base SFCC recipe. `theme/index.ts` composes with
 *      `extendTheme(baseTheme, overrides)`, which DEEP MERGES — a recipe named `Footer` does
 *      not replace SFCC's `Footer`, it inherits it. Shared part names then pick up base
 *      properties, and a key you add that the base lacks is appended last, so a CSS shorthand
 *      can silently reset a longhand the base declared earlier.
 *
 *   4. A bare scale key inside a compound shorthand. Chakra resolves a token only when it is
 *      the entire value; `padding: 'xs 0'` is emitted verbatim, the browser rejects the
 *      declaration, and the padding does not apply at all.
 *
 * A fifth guard below (`no override-component style uses a bare token key on a registered
 * scale`) is a different kind of check — not a wrong-value bug, since `space` and `colors`
 * ARE registered Chakra scales (theme/index.ts), so a bare key there resolves to the correct
 * Zimmermann value either way. It enforces a house style instead: override components must
 * always reference a zimm value via `var(--zimm-scale-*)` / `var(--zimm-color-*)`, never a
 * bare Chakra token string, so a PR reviewer sees an unambiguous zimm reference at every call
 * site instead of having to recall which scales are and are not registered.
 *
 * SCOPE: these guards walk the registered recipe map only (`components` + the composed
 * `theme`). They cannot see the same mistakes made as a JSX prop on a component — there is a
 * live instance of failure mode 2 at `overrides/app/components/header/index.tsx:302`
 * (`fontSize="l"`, which emits nothing) that no test here can reach. Catching that class needs
 * a static rule over JSX attributes (`.coderabbit/ast-grep-rules/`), not a theme walk. The
 * house-style guard has the same JSX blind spot — `footerNavColumn/index.tsx` had a bare
 * `paddingLeft: '2xs'` in an inline `sx` merge (not a recipe) that this test cannot see;
 * it was only found by a manual grep across `overrides/app/components/`, not by this suite.
 */
import { describe, expect, test } from 'vitest';
import theme from '../index';
import { components } from './index';
import { breakpoints } from '../foundation/gridSystem';
import { fontSizes, letterSpacings, lineHeights } from '../foundation/typography';
import { spacing } from '../foundation/spacing';
import { colors } from '../foundation/colour';

const SPACING_KEYS = Object.keys(spacing);

/**
 * Recursively flattens a nested token object into dot-joined path strings — 'text.default',
 * 'action.primary.bgDefault', etc. — mirroring exactly how a recipe would reference it bare
 * (`color: 'text.default'`).
 */
const flattenKeys = (obj: Record<string, unknown>, prefix = ''): string[] =>
  Object.entries(obj).flatMap(([key, value]) => {
    const path = prefix ? `${prefix}.${key}` : key;
    return typeof value === 'object' && value !== null ? flattenKeys(value as Record<string, unknown>, path) : [path];
  });

const COLOR_KEYS = new Set(flattenKeys(colors as unknown as Record<string, unknown>));

/** Every Chakra prop that resolves through the registered `theme.space` scale — the full
 *  padding/margin/gap/inset family, including directional and logical variants. */
const SPACE_PROPS = new Set([
  'padding',
  'margin',
  'gap',
  'inset',
  'p',
  'm',
  'px',
  'py',
  'mx',
  'my',
  'pt',
  'pb',
  'pl',
  'pr',
  'mt',
  'mb',
  'ml',
  'mr',
  'paddingTop',
  'paddingBottom',
  'paddingLeft',
  'paddingRight',
  'paddingBlock',
  'paddingInline',
  'paddingBlockStart',
  'paddingBlockEnd',
  'paddingInlineStart',
  'paddingInlineEnd',
  'marginTop',
  'marginBottom',
  'marginLeft',
  'marginRight',
  'marginBlock',
  'marginInline',
  'marginBlockStart',
  'marginBlockEnd',
  'marginInlineStart',
  'marginInlineEnd',
  'top',
  'left',
  'right',
  'bottom',
]);

/** Every Chakra prop that resolves through the registered `theme.colors` scale. */
const COLOR_PROPS = new Set([
  'color',
  'backgroundColor',
  'bg',
  'background',
  'borderColor',
  'outlineColor',
  'fill',
  'stroke',
]);

const SIZING_PROPS = new Set([
  'width',
  'height',
  'minWidth',
  'maxWidth',
  'minHeight',
  'maxHeight',
  'boxSize',
  'w',
  'h',
  'minW',
  'maxW',
  'minH',
  'maxH',
]);

/**
 * Typography properties whose Zimmermann scale is deliberately not registered as a Chakra
 * scale, mapped to the keys that must never appear bare on them. Each set is that property's
 * own Zimmermann scale keys ∪ the spacing keys, because both spellings fail — differently:
 *
 *   fontSize: '2xs' → resolves against Chakra's default fontSizes: 0.625rem (10px), where the
 *                     Zimmermann `2xs` (0.875rem / 14px) was intended. Plausible, wrong size.
 *   fontSize: '4xs' → no Chakra key, so `font-size: 4xs` is emitted and the browser drops the
 *                     declaration outright. Same for every `lineHeight`/`letterSpacing` key,
 *                     none of which collide with a Chakra default.
 *   fontSize: 'l'   → a spacing key that is not a fontSizes key: dropped the same way.
 *
 * `fontSizes` is the only one of the three with genuine wrong-value collisions; the other two
 * only ever drop the declaration. Both outcomes are worth guarding.
 *
 * Set type with `textStyle` (all 22 Handover styles ARE registered) or var(--zimm-font-*).
 * `fontWeight` is deliberately absent: `medium` is a key in both scales and resolves to 500
 * either way, so keying it the same way would flag a correct declaration.
 */
const TYPOGRAPHY_PROPS = new Map<string, Set<string>>([
  ['fontSize', new Set([...Object.keys(fontSizes), ...SPACING_KEYS])],
  ['lineHeight', new Set([...Object.keys(lineHeights), ...SPACING_KEYS])],
  ['letterSpacing', new Set([...Object.keys(letterSpacings), ...SPACING_KEYS])],
]);

/** Properties that resolve through `theme.space`, where a bare scale key is correct. */
const SPACE_SHORTHANDS = new Set(['padding', 'margin', 'inset', 'gap', 'p', 'm']);

/** Derived from the registered breakpoints so the two cannot drift apart. */
const BREAKPOINT_KEYS = new Set(Object.keys(breakpoints));

/**
 * True when `n` is a responsive *value* container — an array (`['xl','2xl']`) or a
 * breakpoint-keyed object (`{base:'xl', md:'2xl'}`) — rather than a style object. Its keys are
 * therefore positions, not property names, and the property name has to come from the parent.
 *
 * The test is deliberately "are ALL the keys breakpoints?" and not "is ANY key a breakpoint?".
 * That is load-bearing: `xl` and `2xl` are keys in `breakpoints` AND in `spacing`, and
 * `sm`/`md`/`lg` are keys in `breakpoints` AND in `fontSizes`/`lineHeights`/`letterSpacings`.
 * A per-key test cannot tell a responsive map apart from a style object, so only the all-keys
 * form works.
 *
 * A Chakra `sizes`/`variants` map whose every member happens to be named after a breakpoint
 * (`sizes: {md: {...}, lg: {...}}`) does read as responsive here, but harmlessly: the level
 * below it is a real style object, which re-establishes the property name before any leaf is
 * reported.
 */
const isResponsiveContainer = (n: object): boolean =>
  Array.isArray(n) || (Object.keys(n).length > 0 && Object.keys(n).every((k) => BREAKPOINT_KEYS.has(k)));

type Found = { recipe: string; path: string; prop: string; value: string };

/**
 * Recursively walk a style object, including nested media queries, pseudo-selectors and
 * responsive containers. `prop` carries the nearest enclosing property name forward so a leaf
 * inside a responsive container is attributed to the property, not to `0` or `base`.
 */
const walk = (node: unknown, recipe: string, path: string, prop: string, hit: (f: Found) => void): void => {
  if (node === null || typeof node !== 'object') return;
  const responsive = isResponsiveContainer(node);
  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
    const here = path ? `${path}.${key}` : key;
    const p = responsive ? prop : key;
    if (value !== null && typeof value === 'object') {
      walk(value, recipe, here, p, hit);
    } else if (typeof value === 'string') {
      hit({ recipe, path, prop: p, value });
    }
  }
};

/**
 * `recipe.path.prop: 'value'`. For a responsive hit `path` already ends in the property name
 * (the array/breakpoint object sits *under* `fontSize`), so appending `prop` again would read
 * `…fontSize.fontSize`.
 */
const where = (f: Found): string => {
  const segments = f.path ? f.path.split('.') : ['baseStyle'];
  if (segments[segments.length - 1] !== f.prop) segments.push(f.prop);
  return `${f.recipe}.${segments.join('.')}: '${f.value}'`;
};

/** Default resolution props for a function-form baseStyle — all boolean flags false. */
const DEFAULT_STYLE_PROPS: Record<string, unknown> = {
  inverse: false,
  disabled: false,
  hasError: false,
  focused: false,
  filled: false,
  theme,
  colorMode: 'light',
};

/**
 * Every combination of DEFAULT_STYLE_PROPS's boolean-valued entries (theme/colorMode held
 * fixed) — 2^5 = 32 today. A function-form baseStyle can branch its VALUE, not just its
 * shape, on any of these (`top: floated ? '3xs' : '50%'` in zimmTextInput.css.ts), so
 * resolving with only the all-false default can leave a branch's value completely unwalked —
 * '3xs' shipped exactly this way: `floated` is false under the all-default combo, so the
 * guard below never saw the string it was meant to catch. Exhaustive, not sampled: n is
 * small enough that 2^n costs nothing, and a missed combination is the whole failure mode.
 */
const booleanKeys = Object.keys(DEFAULT_STYLE_PROPS).filter((k) => typeof DEFAULT_STYLE_PROPS[k] === 'boolean');
const PROP_COMBINATIONS: Record<string, unknown>[] = Array.from({ length: 2 ** booleanKeys.length }, (_, i) => {
  const combo = { ...DEFAULT_STYLE_PROPS };
  booleanKeys.forEach((key, bit) => {
    combo[key] = Boolean(i & (1 << bit));
  });
  return combo;
});

/** baseStyle may be a plain object or a function of props (see zimmTextInput). Resolves with
 *  the all-false default only — for checks that need just the structural shape (which part
 *  keys exist), not every value a branch could produce. */
const resolveBaseStyle = (recipe: Record<string, unknown>): unknown => {
  const bs = recipe.baseStyle;
  if (typeof bs !== 'function') return bs;
  return (bs as (p: Record<string, unknown>) => unknown)(DEFAULT_STYLE_PROPS);
};

/** Every value a function-form baseStyle can produce, across every prop combination. A
 *  plain-object baseStyle has only the one "combination" (itself). The value-level guards
 *  below walk this, not resolveBaseStyle's single default resolution — see PROP_COMBINATIONS. */
const resolveAllBaseStyles = (recipe: Record<string, unknown>): unknown[] => {
  const bs = recipe.baseStyle;
  if (typeof bs !== 'function') return [bs];
  return PROP_COMBINATIONS.map((props) => (bs as (p: Record<string, unknown>) => unknown)(props));
};

const collect = (): Found[] => {
  const found: Found[] = [];
  for (const [name, recipe] of Object.entries(components)) {
    const r = recipe as unknown as Record<string, unknown>;
    for (const resolved of resolveAllBaseStyles(r)) {
      walk(resolved, name, '', '', (f) => found.push(f));
    }
    for (const section of [r.variants, r.sizes]) {
      walk(section, name, '', '', (f) => found.push(f));
    }
  }
  // resolveAllBaseStyles calls a function-form baseStyle once per prop combination (32
  // today), and most lines don't depend on the varying prop at all — the same Found would
  // otherwise appear dozens of times in a failing test's offender list.
  const seen = new Set<string>();
  return found.filter((f) => {
    const key = where(f);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

describe('recipe guards', () => {
  test('collect() actually walks the registered recipes', () => {
    // Every other test here asserts an empty offender list, which an empty input satisfies
    // just as well as a clean one. Without this, deleting `components` would turn the whole
    // file green.
    expect(Object.keys(components).length).toBeGreaterThan(0);
    expect(collect().length).toBeGreaterThan(0);
  });

  test('no sizing property uses a bare spacing-scale key', () => {
    const offenders = collect()
      .filter((f) => SIZING_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value))
      .map(where);

    // `width: 'xl'` reads theme.sizes.xl (36rem), not space.xl (1.5rem).
    // Use var(--zimm-scale-*), an imported constant, or an explicit unit instead.
    expect(offenders).toEqual([]);
  });

  test('no typography property uses a bare scale key', () => {
    const offenders = collect()
      .filter((f) => TYPOGRAPHY_PROPS.get(f.prop)?.has(f.value) ?? false)
      .map(where);

    // `fontSize: '2xs'` reads Chakra's fontSizes (10px), not the Zimmermann scale (14px);
    // `lineHeight: '2xs'` resolves to nothing at all. Use textStyle or var(--zimm-font-*).
    expect(offenders).toEqual([]);
  });

  test('no compound shorthand contains a bare scale key', () => {
    const offenders = collect()
      .filter((f) => {
        if (!SPACE_SHORTHANDS.has(f.prop)) return false;
        if (!f.value.includes(' ')) return false; // single token is fine
        // Split on whitespace outside var(...) and look for a bare scale key.
        const parts = f.value.replace(/var\([^)]*\)/g, 'VAR').split(/\s+/);
        return parts.some((part) => SPACING_KEYS.includes(part));
      })
      .map(where);

    // Chakra resolves a token only as a whole value. `padding: 'xs 0'` is emitted verbatim
    // and the browser drops the declaration. Use paddingY/paddingX or a var() instead.
    expect(offenders).toEqual([]);
  });

  test('no override-component style uses a bare token key on a registered scale', () => {
    const offenders = collect()
      .filter(
        (f) =>
          (SPACE_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value)) ||
          (COLOR_PROPS.has(f.prop) && COLOR_KEYS.has(f.value)),
      )
      .map(where);

    // Not a wrong-value bug — space and colors ARE registered Chakra scales, so `gap: 'xs'` and
    // `color: 'text.inverse'` already resolve to the correct Zimmermann value. House style
    // instead: use var(--zimm-scale-*) / var(--zimm-color-*) so every call site is an
    // unambiguous zimm reference, not something a reviewer has to check against theme/index.ts's
    // registered-scale list to know whether it's correct.
    expect(offenders).toEqual([]);
  });

  test('no recipe silently inherits a base SFCC recipe of the same name', () => {
    // extendTheme DEEP MERGES. These three intentionally share a base key: Button wants the
    // base variants, and Header/ListMenu are partial overrides of components whose other
    // parts we still rely on. Anything else must be namespaced (e.g. ZimmFooter, not Footer).
    const INTENTIONAL_MERGES = ['Button', 'Header', 'ListMenu'];

    const unexpected = Object.keys(components)
      .filter((name) => !INTENTIONAL_MERGES.includes(name))
      .filter((name) => {
        const ours = resolveBaseStyle(components[name as keyof typeof components] as never) ?? {};
        const merged = resolveBaseStyle((theme.components?.[name] ?? {}) as Record<string, unknown>) ?? {};
        const ourKeys = new Set(Object.keys(ours as object));
        // A key present after composition that we never declared came from the base theme.
        return Object.keys(merged as object).some((k) => !ourKeys.has(k));
      });

    expect(unexpected).toEqual([]);
  });
});

