1	import React, { useCallback } from 'react';
2	import { chakra, useStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmLink } from 'app/components/ui-kits/atoms/zimmLink';
5	import { useCartMessages } from 'app/hooks/useCartMessages';
6	import { usePendingWishlistItem } from './usePendingWishlistItem';
7	import type { WishlistMoveResult } from './usePendingWishlistItem';
8	
9	export type { WishlistMoveResult };
10	
11	const ZIMM_CART_ITEM_ACTIONS_RECIPE = 'ZimmCartItemActions';
12	
13	const messages = defineMessages({
14	  remove: { id: 'zimm_cart_item_actions.remove', defaultMessage: 'Remove' },
15	  moveToWishlist: { id: 'zimm_cart_item_actions.move_to_wishlist', defaultMessage: 'Move to Wishlist' },
16	});
17	
18	export type ZimmCartItemActionsProps = {
19	  /** SFCC product id — the stable identity used to match a resumed pending intent across an auth
20	   *  step, including across a basket merge. See `usePendingWishlistItem`'s own doc for why this
21	   *  is `productId`, not the line's `itemId`. */
22	  productId: string;
23	  /** Interpolated into the wishlist-success toast copy (`useCartMessages.notifyAddedToWishlist`)
24	   *  — never hardcoded at a call site. */
25	  productName: string;
26	  /**
27	   * Whether the current shopper is unauthenticated. Read once by the caller (e.g. from
28	   * `useCustomerType()`) and passed down as a plain prop, rather than this component calling
29	   * that hook itself — see this file's own architecture note below for why.
30	   */
31	  isGuest: boolean;
32	  /**
33	   * Removes this entire line (all units) from the cart — a single call, never looped, regardless
34	   * of the line's current quantity (SFCC-270 AC8 / SFCC-272 AC3). The actual SFCC
35	   * `removeItemFromBasket` call is the caller's own responsibility (SFCC-11 plan step 4.6,
36	   * `cartDrawerContainer.tsx`, not built yet) — this component only ever calls this prop once per
37	   * click, and again (at most once) if a wishlist move succeeds.
38	   */
39	  onRemove: () => void | Promise<void>;
40	  /**
41	   * Attempts the real wishlist-add for an authenticated shopper. The actual SDK call is the
42	   * caller's own responsibility (step 4.6) — this component only calls it and reacts to the
43	   * result. Resolves to a discriminated union so this component can choose the right feedback
44	   * without any data-fetching of its own — see `WishlistMoveResult`'s own doc.
45	   */
46	  onMoveToWishlist: () => Promise<WishlistMoveResult>;
47	  /**
48	   * Called when a guest clicks "Move to Wishlist" for this row, after the pending intent has
49	   * already been persisted (see `usePendingWishlistItem`). The caller is responsible for opening
50	   * the one shared wishlist auth drawer — see this file's own architecture note for why this
51	   * component does not open it directly.
52	   */
53	  onGuestWishlistClick: () => void;
54	};
55	
56	/**
57	 * Molecule — the "Remove" / "Move to Wishlist" action links rendered below a cart line's quantity
58	 * stepper (SFCC-270 AC8, SFCC-272). Supplied by the caller into base `product-item`'s own
59	 * `secondaryActions` slot (already wired, `overrides/app/components/product-item/index.tsx:365`)
60	 * — this molecule does not inject itself into that structure, it is simply the node passed in.
61	 *
62	 * Architecture note — why this component does not call `useWishlistAuthDrawer` itself, despite
63	 * that hook being an auth-gating hook rather than a data-fetching one (so calling it from a
64	 * `ui-kits/` component is not, by itself, a `components.md` container/presentational violation —
65	 * `ZimmWishlistAuthDrawer`, `overrides/app/components/ui-kits/organisms/zimmWishlistAuthDrawer/
66	 * index.tsx:35-58`, is the existing precedent for exactly that). The SFCC-11 plan requires exactly
67	 * ONE `useWishlistAuthDrawer` instance for the whole cart (`intentId: 'cart-wishlist'`), and
68	 * explicitly rejects mounting one instance per line item — a multi-item bag would mount a
69	 * `useForm`, three `useAuthHelper`s, a `useAuthModal` and a drawer per row. Because this component
70	 * is itself rendered once per cart line (one per `secondaryActions` slot), calling that hook
71	 * directly here would reproduce exactly the rejected per-row shape. So the one real hook instance
72	 * must live above every row — the cart container, SFCC-11 plan step 4.6, not yet built — and this
73	 * component receives `isGuest` / `onGuestWishlistClick` as plain props instead, wired by that
74	 * container to its own single hoisted `handleTriggerClick`. `useCartMessages` below has no such
75	 * constraint: it is a stateless wrapper around Chakra's own `useToast()`
76	 * (`overrides/app/hooks/useCartMessages.ts`), safe to call from as many rendered instances as
77	 * there are cart lines — this divergence from a literal per-row hook call is deliberate and
78	 * disclosed in this step's own report, not silently resolved.
79	 *
80	 * @param props see ZimmCartItemActionsProps
81	 */
82	export const ZimmCartItemActions = ({
83	  productId,
84	  productName,
85	  isGuest,
86	  onRemove,
87	  onMoveToWishlist,
88	  onGuestWishlistClick,
89	}: ZimmCartItemActionsProps) => {
90	  const intl = useIntl();
91	  const styles = useStyleConfig(ZIMM_CART_ITEM_ACTIONS_RECIPE);
92	  const { notifyAddedToWishlist, notifyAlreadyInWishlist } = useCartMessages();
93	
94	  // Shared by both the direct (already-authenticated) click path below and the post-auth resume
95	  // path (usePendingWishlistItem's onResume) — one implementation of "branch on the move result",
96	  // not two copies of the same logic.
97	  const attemptMoveToWishlist = useCallback(async () => {
98	    const result = await onMoveToWishlist();
99	    if (result.status === 'success') {
100	      await onRemove();
101	      notifyAddedToWishlist(productName);
102	    } else if (result.status === 'already-in-wishlist') {
103	      notifyAlreadyInWishlist();
104	    }
105	    // 'error': no AC or Figma copy exists for this branch — leave the item in the cart and emit
106	    // no message rather than invent feedback text (same "do not invent copy" principle the
107	    // SFCC-11 plan applies to its own unspecified error feedback elsewhere, e.g. step 5.1).
108	  }, [onMoveToWishlist, onRemove, notifyAddedToWishlist, notifyAlreadyInWishlist, productName]);
109	
110	  const { beginPendingMove } = usePendingWishlistItem({
111	    productId,
112	    isGuest,
113	    onResume: attemptMoveToWishlist,
114	  });
115	
116	  const handleWishlistClick = () => {
117	    if (isGuest) {
118	      beginPendingMove();
119	      onGuestWishlistClick();
120	      return;
121	    }
122	    void attemptMoveToWishlist();
123	  };
124	
125	  return (
126	    <chakra.div __css={styles}>
127	      <ZimmLink size="small" label={intl.formatMessage(messages.remove)} onClick={() => void onRemove()} />
128	      <ZimmLink size="small" label={intl.formatMessage(messages.moveToWishlist)} onClick={handleWishlistClick} />
129	    </chakra.div>
130	  );
131	};
