import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useContentfulEntries } from 'app/hooks/useContentful';
import { CONTENTFUL_FALLBACK_LOCALE } from 'app/config/contentful';
import { ZimmIconAndText } from 'app/components/ui-kits/molecules/zimmIconAndText';
import type { IconAndTextEntry } from 'app/types/contentful';

const ZIMM_BENEFITS_RECIPE = 'ZimmBenefits';

/**
 * Zimmermann Benefits section (SFCC-317). Fetches the `iconAndText` Contentful entry and renders
 * it inside a branded background wrapper. Renders nothing if the entry is unpublished or the fetch
 * fails — surrounding layout is unaffected.
 *
 * Provisional placement: Shipping & Returns PDP drawer tab (until cart drawer ships — SFCC-825/277).
 */
export const ZimmBenefits = () => {
  const styles = useMultiStyleConfig(ZIMM_BENEFITS_RECIPE, {});
  // useMultiSite ships untyped from the base SFCC package — same cast pattern as footer/index.tsx.
  const { locale: siteLocale } = useMultiSite() as { locale?: { id: string } };
  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
  // Filter by placement so the correct entry is always selected, regardless of how many
  // iconAndText entries exist in the space. Contentful field filter syntax: fields.<id>=<value>.
  const { data: entries } = useContentfulEntries<IconAndTextEntry>(
    'iconAndText',
    false,
    locale,
    'fields.placement=benefits',
  );
  const entry = entries?.[0] ?? null;

  if (!entry?.fields.items?.length) return null;

  // Exclude any item whose linked entry or icon asset was not resolved by include=2.
  // An unresolved link has no `fields` property — reading it would throw at the ZimmIconAndText map.
  const resolvedItems = entry.fields.items.filter(
    (item) => item.fields?.icon?.fields?.file != null && item.fields.heading != null,
  );

  if (!resolvedItems.length) return null;

  return (
    <chakra.div __css={styles.root}>
      <ZimmIconAndText
        layout={entry.fields.layout}
        sectionTitle={entry.fields.sectionTitle}
        items={resolvedItems.map((item) => ({
          id: item.sys.id,
          icon: item.fields.icon,
          heading: item.fields.heading,
          description: item.fields.description,
        }))}
      />
    </chakra.div>
  );
};

