import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { isSafeHref } from 'app/utils/safeHref';

type ZimmBadgeProps = {
  /** Badge label, e.g. "Campaign", "Runway", "Exclusive". Rendered uppercase via the recipe. */
  label: string;
  /**
   * Filtered-PLP category URL for this badge (SFCC's `productBadgeUrl`, per .docs/prd/pdp.md
   * §3). Renders as a non-interactive box, not a dead link, when absent or unsafe.
   */
  href?: string;
};

/**
 * Atom — single product badge (Campaign, Runway, Exclusive, Online Exclusive, VIC Exclusive).
 * Renders as a link when `href` is present and passes `isSafeHref`, navigating to that badge's
 * filtered PLP category per .docs/prd/pdp.md §3. Renders as a non-interactive box otherwise,
 * rather than a focusable control with nothing to do.
 *
 * Figma: Zimmermann_Design_System_2026, node 40001471:20752 (State=Primary / State=Hover).
 *
 * @param props see ZimmBadgeProps
 */
export const ZimmBadge = ({ label, href }: ZimmBadgeProps) => {
  const styles = useMultiStyleConfig('ZimmBadge', {});

  if (isSafeHref(href)) {
    return (
      <chakra.a href={href} __css={styles.link}>
        <chakra.span className="zimm-badge-label" __css={styles.label}>
          {label}
        </chakra.span>
      </chakra.a>
    );
  }

  return (
    <chakra.span __css={styles.staticBox}>
      <chakra.span className="zimm-badge-label" __css={styles.label}>
        {label}
      </chakra.span>
    </chakra.span>
  );
};

// Co-located recipe for ZimmBadge — Figma node 40001471:20752 (Zimmermann_Design_System_2026,
// State=Primary / State=Hover). Registered in theme/components/index.ts. Per
// .claude/rules/overrideStyling.md's co-location pattern, governance follows this file's own
// CODEOWNERS entry (owning squad), not theme/components/'s Tier 2 UI-designer gate.
// Figma 40001471:20751 (Primary): white box, 1px border, 4px padding, centred label. Shared by
// both the interactive `link` part and the non-interactive `staticBox` part below — factored out
// so a hover affordance can't leak onto the static variant just because the two share a look.
const badgeBox = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  alignContent: 'stretch',
  padding: 'var(--zimm-scale-2xs)', // 4px
  border: 'var(--zimm-border-width-default) solid var(--zimm-color-border-focus)',
  backgroundColor: 'var(--zimm-color-bg-07)',
  position: 'relative',
  textDecoration: 'none',
  // ZimmProductBadges' row is a flex container with flexWrap:nowrap (Figma-confirmed) — without
  // this, a badge with a long label gets its BOX shrunk to fit the row while the label inside
  // (already flexShrink:0) refuses to shrink, so the text spills past the now-too-narrow
  // border. This is what stops that: the badge box itself never shrinks below its label's
  // natural width, matching the label's own flexShrink:0. See SFCC-132 long-label review.
  flexShrink: 0,
};

export const ZimmBadge = {
  parts: ['link', 'staticBox', 'label'],
  baseStyle: {
    // Used only when ZimmBadge renders a real <a> (safe href present) — carries the hover
    // affordance, since this is the only variant that's actually clickable.
    link: {
      ...badgeBox,
      // Hover recolours both the border (here) and the nested label text (below) — written on
      // this part because the label's own box doesn't necessarily cover every padding pixel of
      // the link, so a hover rule scoped to the label alone could miss a pointer resting in the
      // padding. Figma names these aliases action/primary/bg/hover and
      // action/secondary/text/disabled — both resolve to the same #969696 (zimm grey/300) and
      // are applied here to border/text, not the "bg"/"disabled" purpose their names suggest.
      // That's Figma's own aliasing choice, confirmed against the file's variable defs — not a
      // mistake in this recipe. See SFCC-132.
      _hover: {
        borderColor: 'var(--zimm-color-action-primary-bg-hover)',
        '.zimm-badge-label': {
          color: 'var(--zimm-color-action-secondary-text-disabled)',
        },
      },
    },
    // Used when ZimmBadge renders the non-interactive <span> fallback (no/unsafe href) —
    // identical box, deliberately WITHOUT _hover: a badge that isn't clickable shouldn't react
    // to a pointer resting on it as though it were (CodeRabbit finding, SFCC-132 review).
    staticBox: {
      ...badgeBox,
    },
    // Composite "Default/Input-label" typography (10px size / 500 weight / 18px line-height /
    // 0 letter-spacing) has no registered textStyle in typography.ts — the closest entries
    // (`footer`, `caption`) each diverge on at least one axis. Built from the same --zimm-font-*
    // primitives a matching textStyle would use, per overrideStyling.md hierarchy point 2's
    // individual-piece fallback — every value here already exists in zimmTokens.ts, nothing new
    // added to foundation/. If a second component ever needs this exact combination, promote it
    // to a named textStyles.inputLabel entry in typography.ts instead of copying this block.
    label: {
      fontFamily: 'var(--zimm-font-family-heading)', // medium (500) face
      fontSize: 'var(--zimm-font-size-4xs)', // 10px
      fontWeight: 'var(--zimm-font-weight-medium)', // 500
      lineHeight: 'var(--zimm-font-lineheight-2xs)', // 18px
      letterSpacing: 'var(--zimm-font-letterspacing-sm)', // 0
      color: 'var(--zimm-color-text-default)',
      // Not a bindable Figma variable — inferred from the rendered mock showing "LABEL" in caps.
      textTransform: 'uppercase',
      flexShrink: 0,
      wordBreak: 'break-word',
      // CSS Text Box Trim — trims the line-height dead space above cap-height/below the
      // alphabetic baseline so the label's box matches Figma's measured 15px badge height
      // despite an 18px line-height. Provisional: new to this codebase, no other component
      // relies on it yet — confirm browser support before treating it as a safe default
      // elsewhere. See SFCC-132 design-token audit.
      textBoxTrim: 'trim-both',
      textBoxEdge: 'cap alphabetic',
      // Figma's export sets a fixed w-[25px] on this text node — that's just the auto-measured
      // width of the literal placeholder "LABEL" (5 characters), not a fixed-width design
      // intent. Confirmed with the UI designer (SFCC-132): badge width is auto-length, sized
      // to whatever label it holds — no width set here is deliberate, not an omission.
    },
  },
};

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';

const ZIMM_CART_DRAWER_RECIPE = 'ZimmCartDrawer';

// SFCC-315 builds the drawer shell only — SFCC-277/272 (later commits in this same 18-commit
// plan) will replace this with the real empty-bag component. This placeholder exists only so
// the body isn't blank/broken-looking in the meantime.
const EMPTY_BAG_PLACEHOLDER_TEXT = 'Your bag is empty.';

export type ZimmCartDrawerProps = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button (all via ZimmDrawer/Chakra's Drawer). */
  onClose: () => void;
  /** Number of line items in the bag. Drives the header title ("BAG • {itemCount}" vs
   *  "YOUR BAG IS EMPTY") and whether `children` or the interim empty-state placeholder renders. */
  itemCount: number;
  /** Element to focus once the drawer finishes closing — see ZimmDrawer's own doc (AC10
   *  focus-return); without this Chakra falls back to focusing document.body. */
  finalFocusRef?: React.RefObject<HTMLElement>;
  /** Cart line items. This organism owns no item-rendering logic itself — the caller supplies
   *  the list (SFCC-270's ProductItem, wired in a later commit in this same plan). Rendered only
   *  while itemCount > 0. */
  children: React.ReactNode;
  /** Reserved slot for SFCC-404's message-aggregation system (validation/error/promo banners).
   *  Always rendered, even with nothing passed — see zimmCartDrawer.css.ts's `messages` part:
   *  the band reserves height regardless, so the drawer doesn't change position when a message
   *  appears or disappears. */
  messages?: React.ReactNode;
  /** Reserved slot for SFCC-275's button group (checkout / continue shopping). Not built in this
   *  commit (SFCC-315 is shell-only) — this organism only provides the slot it will render into
   *  later. */
  footer?: React.ReactNode;
};

/**
 * SFCC-315 — the Cart drawer shell. Wraps ZimmDrawer (size="xLarge") with the cart-specific
 * header title, a height-reserving messages band, a responsive items/totals layout, and a
 * footer slot.
 *
 * Deliberately not wired to a trigger yet — no `_app`/`product-view` changes, no
 * `useCartDrawer` hook, no button-group content, no real empty-state body, no message
 * aggregation. All of those are separate, later commits in this same 18-commit plan — this
 * organism is exercised only via its own Storybook stories today.
 *
 * Figma-fidelity audit fix, 2026-09-19: `ZimmDrawer`'s `title` was passed with no `titleStyle`,
 * so it silently took that prop's default (`'large'` → `heading1`, 24px) instead of the Figma
 * spec for this header ("BAG • #", 14px medium — `body2Strong`). Measured live before the fix:
 * 24px/400/32px against the 14px/500 spec. `ZimmDrawer` itself already supports both correctly
 * (`titleStyle="small"` → `body2Strong`, confirmed against `typography.ts`) — this was a missing
 * prop at the call site, not a defect in `ZimmDrawer`.
 *
 * @param props see ZimmCartDrawerProps
 */
export const ZimmCartDrawer = ({
  isOpen,
  onClose,
  itemCount,
  finalFocusRef,
  children,
  messages,
  footer,
}: ZimmCartDrawerProps) => {
  const styles = useMultiStyleConfig(ZIMM_CART_DRAWER_RECIPE, {});
  const title = itemCount === 0 ? 'YOUR BAG IS EMPTY' : `BAG • ${itemCount}`;

  return (
    <ZimmDrawer
      isOpen={isOpen}
      onClose={onClose}
      size="xLarge"
      title={title}
      titleStyle="small"
      finalFocusRef={finalFocusRef}
    >
      <chakra.div __css={styles.messages}>{messages}</chakra.div>
      <chakra.div __css={styles.body}>
        {itemCount === 0 ? <chakra.p textStyle="body2">{EMPTY_BAG_PLACEHOLDER_TEXT}</chakra.p> : children}
      </chakra.div>
      <chakra.div __css={styles.footer}>{footer}</chakra.div>
    </ZimmDrawer>
  );
};

