/**
 * NOT in this step's original file manifest -- added deliberately, disclosed here and in this
 * step's own report rather than silently. The step's own dispatch text names this exact file and
 * calls creating it "acceptable" for proving pass criterion 4 ("Two-to-one column collapse
 * asserted in the recipe test") once nesting this component inside the real `ZimmCartDrawer` for
 * a live check was confirmed impractical (see `zimmCartEmptyState.css.ts`'s own docblock for why:
 * that component does not yet accept this one via `children` at zero items). Mirrors
 * `zimmCartDrawer.css.test.ts`'s own established pattern exactly -- a plain object assertion
 * against the recipe module, not a rendered DOM check. That is a deliberate choice, not a
 * shortcut: Vitest's jsdom environment does not evaluate a real CSS cascade (`@media` conditions
 * are not applied the way a real browser applies them, and layout/`getBoundingClientRect` is not
 * implemented at all), so a rendered-DOM assertion of *this specific* media-query-gated property
 * would not actually prove anything a real browser would agree with. Proving the recipe's own
 * declared value is correct and engine-independent; the true live-rendered proof (this component
 * actually spanning full width with zero dead space) needs a real browser and is covered by this
 * step's own report instead, not by anything under `npm run test`.
 */
import { describe, test, expect } from 'vitest';
import { breakpoints } from 'app/theme/foundation';
import { ZimmCartEmptyState } from './zimmCartEmptyState.css';

const DESKTOP_UP = `@media (min-width: ${breakpoints.xl})`;

describe('ZimmCartEmptyState recipe', () => {
  // SFCC-11 plan step 4.5 pass criterion 4 -- session-notes.md §11.7: "two columns collapse to
  // one". Mutation-tested: temporarily changing `gridColumn: '1 / -1'` to `'1 / 2'` in
  // zimmCartEmptyState.css.ts (confining the component to the first track, reproducing the real
  // bug this recipe exists to prevent) turns this red; restoring it turns it green again.
  test("spans both of ZimmCartDrawer's desktop grid columns at the same breakpoint the drawer switches to its two-column grid", () => {
    expect(ZimmCartEmptyState.baseStyle[DESKTOP_UP]).toEqual({
      gridColumn: '1 / -1',
    });
  });

  // Guards the other half of the same claim: this must NOT be a plain baseStyle property (which
  // would apply unconditionally, including on mobile/tablet's single-column flex body, where a
  // `grid-column` declaration is harmless but signals a misunderstanding of when it's needed) --
  // it must only exist inside the desktop-breakpoint media query, matching exactly where
  // `zimmCartDrawer.css.ts`'s own body style switches `display: flex` to `display: grid`.
  test('declares no grid-span behaviour outside the desktop breakpoint', () => {
    expect((ZimmCartEmptyState.baseStyle as Record<string, unknown>).gridColumn).toBeUndefined();
  });
});

